customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<rect x="5" y="3.5" width="14" height="17" rx="2"/><path d="M9 8h6M9 12h6M9 16h3.5"/>');
var AC={active:'good',seasonal:'warn',retired:'neutral'};
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var catMap=optionMap(ctx.fields,'category'),stnMap=optionMap(ctx.fields,'station'),actMap=optionMap(ctx.fields,'active'),dietMap=optionMap(ctx.fields,'dietary_tags');
  var activeN=0,retiredN=0,dietN=0;
  for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};
    if(a.active==='retired')retiredN++;else activeN++;
    if(Array.isArray(a.dietary_tags)&&a.dietary_tags.length)dietN++;}
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Menu Items',brief(['<b>'+fmtInt(activeN)+'</b> active on the menu','<b>'+fmtInt(dietN)+'</b> with dietary tags',retiredN>0?'<b>'+fmtInt(retiredN)+'</b> retired':'']),'New menu item');
  html+='<div class="kpis">'
    +kpi('Active items',activeN,'<b>'+fmtInt(rows.length)+'</b> on the full list',{hero:true,spark:spark(weekly(rows))})
    +kpi('Dietary-friendly',dietN,'vegan, GF, DF or nut-free')
    +kpi('Retired',retiredN,retiredN>0?'kept for the archive':'nothing shelved yet')
    +'</div>';
  var mHtml='';
  for(var p=0;p<Math.min(7,rows.length);p++){var m=rows[p].answers||{};
    var tags=Array.isArray(m.dietary_tags)?m.dietary_tags:[];
    var tp=tags.length?pill(labelFor(dietMap,tags[0])+(tags.length>1?' +'+(tags.length-1):''),'accent'):pill(labelFor(actMap,m.active),AC[m.active]||'neutral');
    mHtml+=rowItem(h(m.item_name||'Menu item'),h(labelFor(catMap,m.category))+' \u00b7 '+h(labelFor(stnMap,m.station)),'<span class="amt">'+h(mny(m.price))+'</span>'+tp);}
  if(!mHtml)mHtml=emptyBlock(GL,'Menu items you add appear here with price, station and dietary tags.','+ New menu item');
  else mHtml='<div class="rows">'+mHtml+'</div>';
  var bHtml=breakdown(rows,'station',stnMap)||emptyBlock(I.chart,'The station mix takes shape as the menu grows.','+ New menu item');
  html+=sec('Menu library')+'<div class="grid g21">'+panel('The menu',mHtml)+panel('By station',bHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<path d="M6.5 3.5h11v17l-1.8-1.3-1.8 1.3-1.9-1.3-1.9 1.3-1.8-1.3-1.8 1.3z"/><path d="M9.5 8.5h5M9.5 12h5"/>');
var QC={'new':'var(--ax)',making:'var(--fl-warn)',ready:'var(--fl-good)'};
var PK={'new':'accent',making:'warn',ready:'good',served:'neutral'};
function stPill(map,v){if(v==='cancelled')return '<span class="pill" style="color:var(--fl-faint);background:var(--fl-track)">'+h(labelFor(map,v))+'</span>';return pill(labelFor(map,v),PK[v]||'neutral');}
function tOf(s){var d=pd(s);return d?d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}):'';}
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var stMap=optionMap(ctx.fields,'status'),tyMap=optionMap(ctx.fields,'order_type');
  var live=[],servedToday=0,takeN=0,typedN=0;
  for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};var st=a.status;
    if(st==='new'||st==='making'||st==='ready')live.push(rows[i]);
    if(st==='served'&&dayDiff(a.created_at)===0)servedToday++;
    if(a.order_type){typedN++;if(a.order_type==='takeaway')takeN++;}}
  var takePct=typedN?Math.round(takeN/typedN*100):0;
  live.sort(function(x,y){var xd=pd((x.answers||{}).created_at),yd=pd((y.answers||{}).created_at);return (xd?xd.getTime():0)-(yd?yd.getTime():0);});
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Cafe Orders',brief(['<b>'+fmtInt(live.length)+'</b> open now','<b>'+fmtInt(servedToday)+'</b> served today',typedN?'<b>'+fmtInt(takePct)+'%</b> takeaway':'']),'New order');
  html+='<div class="kpis">'
    +kpi('Open orders',live.length,'new, making or ready',{hero:true,spark:spark(weekly(rows))})
    +kpi('Served today',servedToday,servedToday>0?'rung off since open':'none rung off yet today')
    +kpi('Takeaway share',typedN?fmtInt(takePct)+'%':'\u2014','of all orders taken')
    +'</div>';
  var oHtml='';
  for(var b=0;b<Math.min(7,live.length);b++){var o=live[b].answers||{};
    var ttl=o.customer_name||('Walk-in'+(o.order_number?' \u00b7 '+o.order_number:''));
    var where=labelFor(tyMap,o.order_type);
    if(o.order_type==='dine-in'&&o.table_number)where='Table '+o.table_number;
    var dd=dayDiff(o.created_at);
    oHtml+=qRow(QC[o.status]||'var(--ax)',h(ttl),h(where)+(o.items?' \u00b7 '+h(o.items):''),stPill(stMap,o.status)+'<span class="chip">'+h(dd===0?tOf(o.created_at):ago(o.created_at))+'</span>');}
  if(oHtml)oHtml='<div style="margin-top:-8px">'+oHtml+'</div>';
  else if(rows.length){
    for(var p=0;p<Math.min(6,rows.length);p++){var r2=rows[p].answers||{};
      oHtml+=rowItem(h(r2.customer_name||('Walk-in'+(r2.order_number?' \u00b7 '+r2.order_number:''))),h(labelFor(tyMap,r2.order_type))+' \u00b7 '+h(fmtDate(r2.created_at)),stPill(stMap,r2.status)+(num(r2.total)>0?'<span class="chip">'+h(mny(r2.total))+'</span>':''));}
    oHtml='<div class="rows">'+oHtml+'</div>';}
  else oHtml=emptyBlock(GL,'Orders land here the moment they are taken, colored by status.','+ New order');
  var tHtml=breakdown(rows,'order_type',tyMap)||emptyBlock(I.chart,'The dine-in, takeaway and delivery mix shows here.','+ New order');
  html+=sec('Service board')+'<div class="grid g21">'+panel(live.length?'Open orders':'Latest orders',oHtml)+panel('Order types',tHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<path d="M4.5 9.5h12v5.5a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5z"/><path d="M16.5 10.5h1.6a2.4 2.4 0 0 1 0 4.8h-1.85"/><path d="M8 3.5c0 1 .9 1.2.9 2.2S8 6.9 8 7.5M12.5 3.5c0 1 .9 1.2.9 2.2s-.9 1.2-.9 1.8"/>');
var QC={queued:'var(--ax)','pulling-shots':'var(--fl-warn)',pouring:'var(--fl-warn)',ready:'var(--fl-good)'};
var PK={queued:'accent','pulling-shots':'warn',pouring:'warn',ready:'good'};
var ALT={oat:1,almond:1,soy:1};
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var dMap=optionMap(ctx.fields,'drink_type'),mMap=optionMap(ctx.fields,'milk'),sMap=optionMap(ctx.fields,'size'),stMap=optionMap(ctx.fields,'status'),exMap=optionMap(ctx.fields,'extras');
  var rail=[],readyN=0;
  for(var i=0;i<rows.length;i++){if((rows[i].answers||{}).status==='ready')readyN++;else rail.push(rows[i]);}
  var dc=countBy(rows,'drink_type'),topD='',topN=0;
  for(var k in dc){if(dc[k]>topN){topN=dc[k];topD=k;}}
  rail.sort(function(x,y){var xt=pd(x.submittedAt),yt=pd(y.submittedAt);return (xt?xt.getTime():0)-(yt?yt.getTime():0);});
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Barista Queue',brief(['<b>'+fmtInt(rail.length)+'</b> drinks on the rail','<b>'+fmtInt(readyN)+'</b> ready on the pass',topD?h(labelFor(dMap,topD))+' leads the pour count':'']),'New ticket');
  html+='<div class="kpis">'
    +kpi('On the rail',rail.length,'waiting or in the pour',{hero:true,spark:spark(weekly(rows))})
    +kpi('Ready',readyN,'on the pass for pickup')
    +kpi('Most poured',topD?h(labelFor(dMap,topD)):'\u2014',topD?'<b>'+fmtInt(topN)+'</b> tickets all time':'no tickets yet')
    +'</div>';
  var rHtml='';
  for(var b=0;b<Math.min(7,rail.length);b++){var t=rail[b].answers||{};
    var ex=Array.isArray(t.extras)?t.extras:[];var exs=[];
    for(var e2=0;e2<ex.length;e2++)exs.push(labelFor(exMap,ex[e2]));
    rHtml+=qRow(QC[t.status]||'var(--ax)',h(labelFor(dMap,t.drink_type))+' \u00b7 '+h(labelFor(sMap,t.size)),exs.length?h(exs.join(', ')):h(labelFor(stMap,t.status)),(t.milk?pill(labelFor(mMap,t.milk),ALT[t.milk]?'accent':'neutral'):'')+(num(t.shots)>0?'<span class="chip">'+h(fmtInt(t.shots))+' shot'+(num(t.shots)===1?'':'s')+'</span>':''));}
  if(rHtml)rHtml='<div style="margin-top:-8px">'+rHtml+'</div>';
  else if(rows.length){
    for(var p=0;p<Math.min(6,rows.length);p++){var r2=rows[p].answers||{};
      rHtml+=rowItem(h(labelFor(dMap,r2.drink_type))+' \u00b7 '+h(labelFor(sMap,r2.size)),(r2.milk?h(labelFor(mMap,r2.milk)):'')+(num(r2.shots)>0?' \u00b7 '+h(fmtInt(r2.shots))+' shots':''),pill(labelFor(stMap,r2.status),PK[r2.status]||'neutral'));}
    rHtml='<div class="rows">'+rHtml+'</div>';}
  else rHtml=emptyBlock(GL,'Tickets queue here as drinks are called to the machine.','+ New ticket');
  var bHtml=breakdown(rows,'milk',mMap)||emptyBlock(I.chart,'The milk mix shows here once drinks are poured.','+ New ticket');
  html+=sec('Coffee rail')+'<div class="grid g21">'+panel(rail.length?'The rail':'Recently poured',rHtml)+panel('Milk pours',bHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<path d="M9.5 3h5M10 3.5v2.6L7 10.5V20a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1v-9.5l-3-4.4V3.5"/><path d="M7 14.5h10"/>');
var SK={ok:'good',low:'warn',out:'bad'};
var BC={ok:'var(--fl-good)',low:'var(--fl-warn)',out:'var(--fl-bad)'};
function rank(s){return s==='out'?0:s==='low'?1:2;}
function ratio(a){var p=num(a.par_level);return p>0?num(a.current_qty)/p:9;}
function st(a){var q=num(a.current_qty),p=num(a.par_level);if(q<=0)return 'out';if(p>0&&q<p)return 'low';return 'ok';}
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var catMap=optionMap(ctx.fields,'category'),stMap=optionMap(ctx.fields,'status'),unMap=optionMap(ctx.fields,'unit');
  var lowN=0,outN=0,okN=0,latest=null;
  for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};
    var s0=st(a);if(s0==='low')lowN++;else if(s0==='out')outN++;else okN++;
    var d=pd(a.last_checked);if(d&&(!latest||d.getTime()>latest.getTime()))latest=d;}
  var alerts=lowN+outN;
  var cats=Object.keys(countBy(rows,'category')).length;
  var bars=rows.slice().sort(function(x,y){var xa=x.answers||{},ya=y.answers||{};var xr=rank(st(xa)),yr=rank(st(ya));if(xr!==yr)return xr-yr;return ratio(xa)-ratio(ya);});
  var lc=latest?dayDiff(latest):null;
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Stock & Prep',brief(['<b>'+fmtInt(alerts)+'</b> below par','<b>'+fmtInt(okN)+'</b> stocked OK',cats>0?'across <b>'+fmtInt(cats)+'</b> categor'+(cats===1?'y':'ies'):'']),'Stock check');
  html+='<div class="kpis">'
    +kpi('Below par',alerts,alerts>0?'<b>'+fmtInt(lowN)+'</b> low \u00b7 <b>'+fmtInt(outN)+'</b> out':'everything holding at par',{hero:true})
    +kpi('Stocked OK',okN,'at or above par level')
    +kpi('Last stock check',latest?fmtDate(latest):'\u2014',lc==null?'log the first count':lc>0?'next count in '+fmtInt(lc)+'d':lc===0?'checked today':'checked '+fmtInt(-lc)+'d ago')
    +'</div>';
  var pHtml='';
  for(var b=0;b<Math.min(8,bars.length);b++){var s=bars[b].answers||{};var par=num(s.par_level)||Math.max(num(s.current_qty),1);
    pHtml+=barRow((s.item||'Item')+' \u00b7 '+labelFor(unMap,s.unit),num(s.current_qty),par,BC[st(s)]||'var(--fl-accent)');}
  if(!pHtml)pHtml=emptyBlock(GL,'Each line fills toward its par level here, low and out first.','+ Stock check');
  var cHtml=breakdown(rows,'category',catMap)||emptyBlock(I.chart,'The pantry takes shape by category as you log lines.','+ Stock check');
  html+=sec('Prep fridge')+'<div class="grid g21">'+panel('Par levels',pHtml)+panel('By category',cHtml)+'</div>';
  var rrHtml='',rrN=0;
  for(var q=0;q<bars.length&&rrN<6;q++){var v=bars[q].answers||{};var vs=st(v);if(vs!=='low'&&vs!=='out')continue;rrN++;
    rrHtml+=rowItem(h(v.item||'Item'),(v.supplier?'from '+h(v.supplier)+' \u00b7 ':'')+h(labelFor(catMap,v.category)),pill(labelFor(stMap,vs),SK[vs]||'neutral')+'<span class="chip">'+h(fmtInt(num(v.current_qty)))+' of '+h(fmtInt(num(v.par_level)))+' '+h(labelFor(unMap,v.unit))+'</span>');}
  if(!rrHtml)rrHtml=emptyBlock(I.check,'Nothing to reorder \u2014 the pantry is holding at par.','+ Stock check');
  else rrHtml='<div class="rows">'+rrHtml+'</div>';
  var checked=rows.slice().sort(function(x,y){var xd=pd((x.answers||{}).last_checked),yd=pd((y.answers||{}).last_checked);return (yd?yd.getTime():0)-(xd?xd.getTime():0);});
  var ckHtml='';
  for(var p=0;p<Math.min(5,checked.length);p++){var c2=checked[p].answers||{};if(!c2.last_checked)continue;
    ckHtml+=rowItem(h(c2.item||'Item'),h(labelFor(catMap,c2.category)),'<span class="chip">'+h(fmtDate(c2.last_checked))+'</span>');}
  if(!ckHtml)ckHtml=emptyBlock(I.clock,'Count dates land here as lines are checked off.','+ Stock check');
  else ckHtml='<div class="rows">'+ckHtml+'</div>';
  html+=sec('Reorder calls')+'<div class="grid g21">'+panel('Call the supplier',rrHtml)+panel('Latest counts',ckHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<circle cx="9" cy="8.5" r="3.25"/><path d="M2.5 20c.6-3 3.2-4.5 6.5-4.5s5.9 1.5 6.5 4.5"/><path d="M15.5 5.6a3.25 3.25 0 0 1 0 5.8M17.6 15.9c2 .6 3.5 1.9 3.9 4.1"/>');
function dayLbl(dd,dateStr){if(dd===0)return 'Today';if(dd===1)return 'Tomorrow';var d=pd(dateStr);return d?d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}):'Undated';}
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var roleMap=optionMap(ctx.fields,'role'),stnMap=optionMap(ctx.fields,'station');
  var todayN=0,weekN=0,barToday=0,firstIn=null,up=[];
  for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};var dd=dayDiff(a.shift_date);
    if(dd===0){todayN++;if(a.role==='barista')barToday++;var st=String(a.start_time||'');if(st&&(firstIn===null||st<firstIn))firstIn=st;}
    if(dd!=null&&dd>=0&&dd<=6)weekN++;
    if(dd!=null&&dd>=0)up.push({a:a,dd:dd});}
  up.sort(function(x,y){return x.dd-y.dd||String(x.a.start_time||'').localeCompare(String(y.a.start_time||''));});
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Staff Roster',brief(['<b>'+fmtInt(todayN)+'</b> behind the bar today',todayN>0&&firstIn?'first in at <b>'+h(fmtTime(firstIn))+'</b>':'<b>'+fmtInt(weekN)+'</b> shift'+(weekN===1?'':'s')+' this week',barToday>0?'<b>'+fmtInt(barToday)+'</b> barista'+(barToday===1?'':'s')+' on':'']),'Roster shift');
  html+='<div class="kpis">'
    +kpi('On today',todayN,todayN>0?(firstIn?'first in at <b>'+h(fmtTime(firstIn))+'</b>':'on the roster'):'no shifts rostered today',{hero:true,spark:spark(weekly(rows))})
    +kpi('Baristas today',barToday,todayN>0?'of <b>'+fmtInt(todayN)+'</b> on shift':'roster one for the rush')
    +kpi('This week',weekN,'shifts over the next 7 days')
    +'</div>';
  var schHtml='';
  if(up.length){var opn=false,lastD=null;
    for(var b=0;b<Math.min(8,up.length);b++){var e=up[b];
      if(e.dd!==lastD||!opn){if(opn)schHtml+='</div>';schHtml+='<div class="day"><div class="day-h">'+h(dayLbl(e.dd,e.a.shift_date))+'</div>';opn=true;lastD=e.dd;}
      schHtml+='<div class="sch"><span class="sch-t num">'+(h(fmtTime(e.a.start_time))||'\u2014')+'</span><div class="row-main"><div class="row-title">'+h(e.a.name||'Crew')+'</div><div class="row-sub">'+h(labelFor(roleMap,e.a.role))+' \u00b7 '+h(labelFor(stnMap,e.a.station))+'</div></div><div class="row-r">'+(e.a.end_time?'<span class="chip">to '+h(fmtTime(e.a.end_time))+'</span>':'')+'</div></div>';}
    if(opn)schHtml+='</div>';}
  else if(rows.length){
    for(var p=0;p<Math.min(6,rows.length);p++){var r2=rows[p].answers||{};
      schHtml+=rowItem(h(r2.name||'Crew'),h(labelFor(roleMap,r2.role))+' \u00b7 '+h(labelFor(stnMap,r2.station)),'<span class="chip">'+h(fmtDate(r2.shift_date))+'</span>');}
    schHtml='<div class="rows">'+schHtml+'</div>';}
  else schHtml=emptyBlock(GL,'Shifts you roster appear here, grouped by day.','+ Roster shift');
  var bHtml=breakdown(rows,'role',roleMap)||emptyBlock(I.chart,'Role coverage shows here once the roster fills.','+ Roster shift');
  html+=sec('Behind the bar')+'<div class="grid g21">'+panel(up.length?'Today & upcoming':'Latest shifts',schHtml)+panel('By role',bHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var GL=icoSvg('<path d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z"/>');
function dLbl(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}):'Undated';}
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
  var rows=await recs(500);
  var clMap=optionMap(ctx.fields,'cleaning');
  var totT=Object.keys(clMap).length||6;
  var byDate=rows.slice().sort(function(x,y){var xd=pd((x.answers||{}).close_date),yd=pd((y.answers||{}).close_date);return (yd?yd.getTime():0)-(xd?xd.getTime():0);});
  var list=[];
  for(var i=0;i<byDate.length;i++){var dd=dayDiff((byDate[i].answers||{}).close_date);if(dd!=null&&dd<=0)list.push(byDate[i]);}
  if(!list.length)list=byDate;
  var last=list.length?list[0]:null,la=last?last.answers||{}:{};
  var now=new Date(),mStart=new Date(now.getFullYear(),now.getMonth(),1).getTime(),mEnd=new Date(now.getFullYear(),now.getMonth()+1,1).getTime();
  var monthN=0;
  for(var m2=0;m2<rows.length;m2++){var md=pd((rows[m2].answers||{}).close_date);if(md&&md.getTime()>=mStart&&md.getTime()<mEnd)monthN++;}
  var trend=[];
  for(var t2=Math.min(8,list.length)-1;t2>=0;t2--)trend.push(num((list[t2].answers||{}).register_total));
  var html='<div class="wrap">';
  html+=headerBlock(GL,ctx.title||'Daily Close',brief([last?'last close <b>'+mnyC(la.register_total)+'</b>':'',last?'tips <b>'+mny(la.tips)+'</b>':'','<b>'+fmtInt(monthN)+'</b> close'+(monthN===1?'':'s')+' this month']),'Daily close');
  html+='<div class="kpis">'
    +kpi('Last close',last?mnyC(la.register_total):'\u2014',last?'rung off '+h(fmtDate(la.close_date)):'no closes recorded yet',{hero:true,spark:spark(trend)})
    +kpi('Tips last close',last?mny(la.tips):'\u2014',last?'shared by the crew':'logged with each close')
    +kpi('Closes this month',monthN,'since the 1st')
    +'</div>';
  var rHtml='';
  for(var p=0;p<Math.min(6,list.length);p++){var c=list[p].answers||{};
    var done=Array.isArray(c.cleaning)?c.cleaning.length:0;
    rHtml+=rowItem(h(dLbl(c.close_date)),'Beans '+h(fmtInt(num(c.beans_used)))+' kg \u00b7 milk '+h(fmtInt(num(c.milk_used)))+' L \u00b7 checklist '+h(fmtInt(done))+'/'+h(fmtInt(totT)),'<span class="amt">'+h(mny(c.register_total))+'</span><span class="chip">tips '+h(mny(c.tips))+'</span>');}
  if(!rHtml)rHtml=emptyBlock(GL,'Each close-down lands here with the register, tips and checklist.','+ Daily close');
  else rHtml='<div class="rows">'+rHtml+'</div>';
  var u=list.slice(0,5),mxB=0,mxM=0,j;
  for(j=0;j<u.length;j++){var ua=u[j].answers||{};if(num(ua.beans_used)>mxB)mxB=num(ua.beans_used);if(num(ua.milk_used)>mxM)mxM=num(ua.milk_used);}
  var uHtml='';
  if(mxB>0){uHtml+='<div class="day"><div class="day-h">Beans used (kg)</div>';for(j=0;j<u.length;j++){var b2=u[j].answers||{};uHtml+=barRow(fmtDate(b2.close_date),num(b2.beans_used),mxB,'var(--fl-accent)');}uHtml+='</div>';}
  if(mxM>0){uHtml+='<div class="day"><div class="day-h">Milk used (litres)</div>';for(j=0;j<u.length;j++){var m3=u[j].answers||{};uHtml+=barRow(fmtDate(m3.close_date),num(m3.milk_used),mxM,'var(--fl-warn)');}uHtml+='</div>';}
  if(!uHtml)uHtml=emptyBlock(I.chart,'Beans and milk usage trends show here after a few closes.','+ Daily close');
  html+=sec('Close-down ritual')+'<div class="grid g21">'+panel('Recent closes',rHtml)+panel('Usage',uHtml)+'</div>';
  html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
.tot{display:flex;justify-content:space-between;margin-top:10px;padding-top:10px;border-top:1px solid var(--fl-border);font-size:12px;color:var(--fl-muted);}
.tot b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function fmtDateY(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function findForm(ctx,name){var t=String(name).toLowerCase();for(var i=0;i<ctx.forms.length;i++){if(String(ctx.forms[i].displayName||'').toLowerCase()===t)return ctx.forms[i];}return null;}
function optionMap(form,fieldId){var m={};if(!form||!form.fields)return m;for(var i=0;i<form.fields.length;i++){var f=form.fields[i];if(f.id===fieldId&&f.properties&&f.properties.options){var o=f.properties.options;for(var j=0;j<o.length;j++){m[o[j].value]=o[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(form,limit){if(!form)return [];try{return await FL.records(form.formId,{limit:limit||500});}catch(e){return [];}}
function nameMap(records,fn){var m={};for(var i=0;i<records.length;i++){var r=records[i];m[r.id]=fn(r.answers||{},r)||'';}return m;}
function refName(map,v){if(v==null||v==='')return '';if(Array.isArray(v))v=v[0];return map[v]||'';}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
