I.tag=icoSvg('<path d="M3.5 11.3V4.5a1 1 0 0 1 1-1h6.8a1 1 0 0 1 .7.3l8.2 8.2a1.5 1.5 0 0 1 0 2.1l-6.1 6.1a1.5 1.5 0 0 1-2.1 0L3.8 12a1 1 0 0 1-.3-.7z"/><circle cx="8" cy="8" r="1.25"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body,nav,navLabel){return '<div class="panel">'+(title?'<div class="panel-h"><div class="panel-t">'+h(title)+'</div>'+(nav?'<button class="panel-link" data-nav="'+h(nav)+'">'+h(navLabel||'View all')+'</button>':'')+'</div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=(max>0&&count>0)?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,nav,cta){return '<div class="empty">'+(ic||'')+h(msg)+(nav?'<div><button class="link-btn" data-nav="'+h(nav)+'">'+h(cta||'+ Add one')+'</button></div>':'')+'</div>';}
function acts(items){var out='<div class="acts">';for(var i=0;i<items.length;i++){var it=items[i];if(!it||!it.nav)continue;out+='<button class="act" data-nav="'+h(it.nav)+'">'+(it.icon||I.plus)+'<span>'+h(it.label)+'</span></button>';}out+='</div>';return out;}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,ctas){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(ctas&&ctas.length){out+='<div class="hdr-r">';for(var i=0;i<ctas.length;i++){var c2=ctas[i];if(!c2||!c2.nav)continue;out+='<button class="btn '+(c2.ghost?'btn-ghost':'btn-primary')+'" data-nav="'+h(c2.nav)+'">'+(c2.icon||'')+'<span>'+h(c2.label)+'</span></button>';}out+='</div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var nav=root.querySelectorAll('[data-nav]');for(var i=0;i<nav.length;i++){(function(el){el.addEventListener('click',function(){var t=el.getAttribute('data-nav');if(t)FL.navigate(t);});})(nav[i]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var CG=icoSvg('<path d="M4.5 9.5h12v5.5a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5z"/><path d="M16.5 10.5h1.6a2.4 2.4 0 0 1 0 4.8h-1.85"/><path d="M8 3.5c0 1 .9 1.2.9 2.2S8 6.9 8 7.5M12.5 3.5c0 1 .9 1.2.9 2.2s-.9 1.2-.9 1.8"/>');
var OC={'new':'var(--ax)',making:'var(--fl-warn)',ready:'var(--fl-good)'};
var OP={'new':'accent',making:'warn',ready:'good',served:'neutral'};
var TP={queued:'accent','pulling-shots':'warn',pouring:'warn',ready:'good'};
function stPill(map,v){if(v==='cancelled')return '<span class="pill" style="color:var(--fl-faint);background:var(--fl-track)">'+h(labelFor(map,v))+'</span>';return pill(labelFor(map,v),OP[v]||'neutral');}
function tOf(s){var d=pd(s);return d?d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}):'';}
function dayLbl(dd,dateStr){if(dd===0)return 'Today';if(dd===1)return 'Tomorrow';var d=pd(dateStr);return d?d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}):'Undated';}
async function main(){
  var root=document.getElementById('app');
  var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this dashboard.');}
  var fO=findForm(ctx,'Cafe Orders'),fB=findForm(ctx,'Barista Queue'),fS=findForm(ctx,'Stock & Prep'),fR=findForm(ctx,'Staff Roster'),fD=findForm(ctx,'Daily Closes');
  var r=await Promise.all([recs(fO),recs(fB),recs(fS),recs(fR),recs(fD)]);
  var orders=r[0],tix=r[1],stock=r[2],shifts=r[3],closes=r[4];
  var oMap=optionMap(fO,'status'),tyMap=optionMap(fO,'order_type');
  var dMap=optionMap(fB,'drink_type'),szMap=optionMap(fB,'size'),mkMap=optionMap(fB,'milk'),tsMap=optionMap(fB,'status');
  var ssMap=optionMap(fS,'status'),unMap=optionMap(fS,'unit');
  var roleMap=optionMap(fR,'role'),stnMap=optionMap(fR,'station');
  var live=[],newN=0,makingN=0,readyN=0;
  for(var i=0;i<orders.length;i++){var oa=orders[i].answers||{};var st=oa.status;
    if(st==='new'){newN++;live.push(orders[i]);}
    else if(st==='making'){makingN++;live.push(orders[i]);}
    else if(st==='ready'){readyN++;live.push(orders[i]);}}
  live.sort(function(x,y){var xd=pd((x.answers||{}).created_at),yd=pd((y.answers||{}).created_at);return (xd?xd.getTime():0)-(yd?yd.getTime():0);});
  var rail=[],tReady=0;
  for(var t1=0;t1<tix.length;t1++){if((tix[t1].answers||{}).status==='ready')tReady++;else rail.push(tix[t1]);}
  rail.sort(function(x,y){var xt=pd(x.submittedAt),yt=pd(y.submittedAt);return (xt?xt.getTime():0)-(yt?yt.getTime():0);});
  var lowS=[],lowN=0,outN=0;
  for(var s1=0;s1<stock.length;s1++){var sa=stock[s1].answers||{};if(sa.status==='out'){outN++;lowS.push(stock[s1]);}else if(sa.status==='low'){lowN++;lowS.push(stock[s1]);}}
  lowS.sort(function(x,y){var xs=(x.answers||{}).status,ys=(y.answers||{}).status;return (xs==='out'?0:1)-(ys==='out'?0:1);});
  var alerts=lowN+outN;
  var todayN=0,up=[];
  for(var h1=0;h1<shifts.length;h1++){var ha=shifts[h1].answers||{};var hd=dayDiff(ha.shift_date);
    if(hd===0)todayN++;
    if(hd!=null&&hd>=0)up.push({a:ha,dd:hd});}
  up.sort(function(x,y){return x.dd-y.dd||String(x.a.start_time||'').localeCompare(String(y.a.start_time||''));});
  var byDate=closes.slice().sort(function(x,y){var xd=pd((x.answers||{}).close_date),yd=pd((y.answers||{}).close_date);return (yd?yd.getTime():0)-(xd?xd.getTime():0);});
  var last=null,closedToday=false;
  for(var c1=0;c1<byDate.length;c1++){var cd=dayDiff((byDate[c1].answers||{}).close_date);if(cd===0)closedToday=true;if(cd!=null&&cd<=0&&!last)last=byDate[c1];}
  var la=last?last.answers||{}:{};
  var html='<div class="wrap">';
  html+=headerBlock(CG,ctx.appName||'BrewDesk',brief(['<b>'+fmtInt(live.length)+'</b> open order'+(live.length===1?'':'s'),'<b>'+fmtInt(rail.length)+'</b> on the rail',alerts>0?'<b>'+fmtInt(alerts)+'</b> stock alert'+(alerts===1?'':'s'):'pantry at par',closedToday?'till closed today':'till close pending']),[{nav:fO?fO.formId:'',label:'New order',icon:I.plus},{nav:fB?fB.formId:'',label:'Barista ticket',icon:CG,ghost:true}]);
  html+='<div class="kpis">'
    +kpi('Open orders',live.length,orders.length?'<b>'+fmtInt(newN)+'</b> new \u00b7 <b>'+fmtInt(makingN)+'</b> making \u00b7 <b>'+fmtInt(readyN)+'</b> ready':'No orders yet',{hero:true,spark:spark(weekly(orders))})
    +kpi('On the rail',rail.length,tReady>0?'<b>'+fmtInt(tReady)+'</b> ready on the pass':'drinks in the make')
    +kpi('Stock alerts',alerts,alerts>0?'<span style="color:var(--fl-bad);font-weight:650">'+fmtInt(outN)+' out \u00b7 '+fmtInt(lowN)+' low</span>':'everything at par')
    +kpi('Till today',closedToday?'Closed':'Open',last?'last close <b>'+mnyC(la.register_total)+'</b>':'no closes recorded yet')
    +'</div>';
  var loHtml='';
  for(var b=0;b<Math.min(7,live.length);b++){var o=live[b].answers||{};
    var ttl=o.customer_name||('Walk-in'+(o.order_number?' \u00b7 '+o.order_number:''));
    var where=labelFor(tyMap,o.order_type);
    if(o.order_type==='dine-in'&&o.table_number)where='Table '+o.table_number;
    var dd3=dayDiff(o.created_at);
    loHtml+=qRow(OC[o.status]||'var(--ax)',h(ttl),h(where)+(o.items?' \u00b7 '+h(o.items):''),stPill(oMap,o.status)+'<span class="chip">'+h(dd3===0?tOf(o.created_at):ago(o.created_at))+'</span>');}
  if(loHtml)loHtml='<div style="margin-top:-8px">'+loHtml+'</div>';
  else if(orders.length){
    for(var p1=0;p1<Math.min(6,orders.length);p1++){var r2=orders[p1].answers||{};
      loHtml+=rowItem(h(r2.customer_name||('Walk-in'+(r2.order_number?' \u00b7 '+r2.order_number:''))),h(labelFor(tyMap,r2.order_type))+' \u00b7 '+h(fmtDate(r2.created_at)),stPill(oMap,r2.status)+(num(r2.total)>0?'<span class="chip">'+h(mny(r2.total))+'</span>':''));}
    loHtml='<div class="rows">'+loHtml+'</div>';}
  else loHtml=emptyBlock(I.doc,'Orders appear here the moment the counter takes them.',fO?fO.formId:'','+ New order');
  var tyHtml=breakdown(orders,'order_type',tyMap);
  tyHtml=tyHtml?tyHtml+'<div class="tot"><span>Orders taken</span><b class="num">'+fmtInt(orders.length)+'</b></div>':emptyBlock(I.chart,'The dine-in, takeaway and delivery mix shows here.',fO?fO.formId:'','+ New order');
  html+=sec('Service board')+'<div class="grid g21">'+panel(live.length?'Live orders':'Latest orders',loHtml,fO?'form/'+fO.formId+'/responses':'')+panel('Order types',tyHtml,fO?'form/'+fO.formId+'/responses':'')+'</div>';
  var rlHtml='';
  for(var q1=0;q1<Math.min(5,rail.length);q1++){var t=rail[q1].answers||{};
    rlHtml+=rowItem(h(labelFor(dMap,t.drink_type))+' \u00b7 '+h(labelFor(szMap,t.size)),(t.milk?h(labelFor(mkMap,t.milk)):'')+(num(t.shots)>0?' \u00b7 '+h(fmtInt(t.shots))+' shot'+(num(t.shots)===1?'':'s'):''),pill(labelFor(tsMap,t.status),TP[t.status]||'neutral'));}
  if(rlHtml)rlHtml='<div class="rows">'+rlHtml+'</div>';
  else rlHtml=emptyBlock(CG,'Barista tickets queue here as drinks are called.',fB?fB.formId:'','+ Barista ticket');
  var lsHtml='';
  for(var q2=0;q2<Math.min(5,lowS.length);q2++){var v=lowS[q2].answers||{};
    lsHtml+=rowItem(h(v.item||'Item'),h(fmtInt(num(v.current_qty)))+' of '+h(fmtInt(num(v.par_level)))+' '+h(labelFor(unMap,v.unit))+(v.supplier?' \u00b7 '+h(v.supplier):''),pill(labelFor(ssMap,v.status),v.status==='out'?'bad':'warn'));}
  if(lsHtml)lsHtml='<div class="rows">'+lsHtml+'</div>';
  else lsHtml=emptyBlock(I.check,'Pantry is at par \u2014 nothing needs a reorder.',fS?fS.formId:'','+ Stock check');
  html+=sec('Bar & pantry')+'<div class="grid g11">'+panel('Coffee rail',rlHtml,fB?'form/'+fB.formId+'/responses':'')+panel('Low stock',lsHtml,fS?'form/'+fS.formId+'/responses':'')+'</div>';
  var rsHtml='';
  if(up.length){var opn=false,lastD=null;
    for(var u1=0;u1<Math.min(6,up.length);u1++){var e=up[u1];
      if(e.dd!==lastD||!opn){if(opn)rsHtml+='</div>';rsHtml+='<div class="day"><div class="day-h">'+h(dayLbl(e.dd,e.a.shift_date))+'</div>';opn=true;lastD=e.dd;}
      rsHtml+='<div class="sch"><span class="sch-t num">'+(h(fmtTime(e.a.start_time))||'\u2014')+'</span><div class="row-main"><div class="row-title">'+h(e.a.name||'Crew')+'</div><div class="row-sub">'+h(labelFor(roleMap,e.a.role))+' \u00b7 '+h(labelFor(stnMap,e.a.station))+'</div></div><div class="row-r">'+(e.a.end_time?'<span class="chip">to '+h(fmtTime(e.a.end_time))+'</span>':'')+'</div></div>';}
    if(opn)rsHtml+='</div>';}
  else if(shifts.length){
    for(var p2=0;p2<Math.min(5,shifts.length);p2++){var sh=shifts[p2].answers||{};
      rsHtml+=rowItem(h(sh.name||'Crew'),h(labelFor(roleMap,sh.role))+' \u00b7 '+h(labelFor(stnMap,sh.station)),'<span class="chip">'+h(fmtDate(sh.shift_date))+'</span>');}
    rsHtml='<div class="rows">'+rsHtml+'</div>';}
  else rsHtml=emptyBlock(I.users,'Shifts you roster show here, grouped by day.',fR?fR.formId:'','+ Roster shift');
  var poCounts=countBy(tix,'drink_type'),poKeys=Object.keys(poCounts);
  poKeys.sort(function(x,y){return poCounts[y]-poCounts[x];});poKeys=poKeys.slice(0,5);
  var poHtml='',poMax=poKeys.length?poCounts[poKeys[0]]:0;
  for(var v2=0;v2<poKeys.length;v2++){poHtml+=barRow(labelFor(dMap,poKeys[v2]),poCounts[poKeys[v2]],poMax);}
