  html+=sec('Crew & the pour')+'<div class="grid g21">'+panel(up.length?'On the roster':'Latest shifts',rsHtml,fR?'form/'+fR.formId+'/responses':'')+panel('Most poured',poHtml,fB?'form/'+fB.formId+'/responses':'')+'</div>';
  html+=sec('Quick actions')+acts([{nav:fO?fO.formId:'',label:'New order',icon:I.doc},{nav:fB?fB.formId:'',label:'Barista ticket',icon:CG},{nav:fS?fS.formId:'',label:'Stock check',icon:I.box},{nav:fD?fD.formId:'',label:'Daily close',icon:I.money}]);
  html+='</div>';root.innerHTML=html;wire(root);
}
main();
